-- Template bodies are piped into remote/template_tokens.py on the host; only tokens/metadata leave the host.
SELECT CONVERT('sp_templates' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(templateid USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(name USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(module USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(IFNULL(spcompany,'') USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(template USING utf8mb4) COLLATE utf8mb4_general_ci body FROM sp_templates
UNION ALL SELECT CONVERT('sp_templates_header_footer' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(templateid USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(CONCAT(name,' [hdr/ftr sizes ',header_size,'/',footer_size,' orient ',page_orientation,']') USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(module USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(IFNULL(spcompany,'') USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci body FROM sp_templates
UNION ALL SELECT CONVERT('quotingtool' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(id USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(filename USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(module USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(CONCAT('active=',is_active,' deleted=',deleted) USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(CONCAT(IFNULL(header,''),IFNULL(content,''),IFNULL(body,''),IFNULL(footer,'')) USING utf8mb4) COLLATE utf8mb4_general_ci body FROM vtiger_quotingtool
UNION ALL SELECT CONVERT('emailtemplate' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(templateid USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(templatename USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(IFNULL(module,'') USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(CONCAT('system=',systemtemplate,' deleted=',deleted) USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(CONCAT(IFNULL(subject,''),' ',IFNULL(body,'')) USING utf8mb4) COLLATE utf8mb4_general_ci body FROM vtiger_emailtemplates
UNION ALL SELECT CONVERT('notificationscheduler' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(schedulednotificationid USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(schedulednotificationname USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(IFNULL(type,'') USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(CONCAT('active=',active) USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(CONCAT(IFNULL(notificationsubject,''),' ',IFNULL(notificationbody,'')) USING utf8mb4) COLLATE utf8mb4_general_ci body FROM vtiger_notificationscheduler
UNION ALL SELECT CONVERT('inventorynotification' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(notificationid USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(notificationname USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT(IFNULL(label,'') USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT(IFNULL(status,'') USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(CONCAT(IFNULL(notificationsubject,''),' ',IFNULL(notificationbody,'')) USING utf8mb4) COLLATE utf8mb4_general_ci body FROM vtiger_inventorynotification
UNION ALL SELECT CONVERT('inventory_tandc' USING utf8mb4) COLLATE utf8mb4_general_ci kind, CONVERT(id USING utf8mb4) COLLATE utf8mb4_general_ci id, CONVERT(type USING utf8mb4) COLLATE utf8mb4_general_ci name, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci module, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci company, CONVERT(IFNULL(tandc,'') USING utf8mb4) COLLATE utf8mb4_general_ci body FROM vtiger_inventory_tandc;
